<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\UserProfileBirthdateVO;

trait UserProfileBirthdateAttributeHolder
{
    protected UserProfileBirthdateVO|string|null $birthdate = null;
    protected bool $birthdateAssigned = false;

    public function getBirthdateOrCurrent(?UserProfileBirthdateVO $birthdate): ?UserProfileBirthdateVO
    {
        return $this->birthdateAssigned ? ($this->birthdate === null ? null : UserProfileBirthdateVO::from($this->birthdate)) : $birthdate;
    }
    public function birthdateTryBuildInitial(ConstraintFailList $error): ?UserProfileBirthdateVO
    {
        return  UserProfileBirthdateVO::tryFrom($this->birthdateAssigned ? $this->birthdate : null, $error);
    }
    public function birthdate(UserProfileBirthdateVO|string|null $birthdate): static
    {
        $this->birthdate = $birthdate;
        $this->birthdateAssigned = true;
        return $this;
    }
    public function getBirthdate(): ?string
    {
        return $this->birthdate instanceof UserProfileBirthdateVO ? $this->birthdate->value() : $this->birthdate;
    }
    public function isBirthdateAssigned(): bool
    {
        return $this->birthdateAssigned;
    }
    public function writeBirthdateTo(mixed $att): void
    {
        if ($this->birthdateAssigned) {
            $att->birthdate($this->birthdate);
        }
    }
    public function readBirthdateFrom(mixed $att): void
    {
        if ($att->isBirthdateAssigned()) {
            $birthdate = $att->getBirthdate();
            $this->birthdate($birthdate);
        }
    }
    public function unsetBirthdate(): static
    {
        $this->birthdateAssigned = false;
        return $this;
    }
    protected function withDefaultBirthdate(): void
    {
    }
    protected function withAssertedBirthdateRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->birthdateAssigned = $this->birthdateAssigned) {
            $value->birthdate = UserProfileBirthdateVO::tryFrom($this->birthdate, $errorsList);
        }
    }
}
